def transform(grid):
    R, C = len(grid), len(grid[0])
    h, w = R // 2, C // 2

    # Split into four quadrants
    TL = [row[:w] for row in grid[:h]]
    TR = [row[w:] for row in grid[:h]]
    BL = [row[:w] for row in grid[h:]]
    BR = [row[w:] for row in grid[h:]]

    # Count and find mode (background) for each quadrant
    from collections import Counter
    def mode(q):
        c = Counter()
        for row in q:
            for x in row:
                c[x] += 1
        return c.most_common(1)[0][0]

    # Key insight: output background is most common across all quadrants combined
    all_cells = []
    for q in [TL, TR, BL, BR]:
        for row in q:
            for x in row:
                all_cells.append(x)
    bg = Counter(all_cells).most_common(1)[0][0]

    result = []
    for i in range(h):
        row = []
        for j in range(w):
            # Check all quadrants in order. First non-background (different from global bg) wins?
            # Actually, check if each quadrant cell differs from its OWN background
            # If so, it's a "signal"

            tl, tr, bl, br = TL[i][j], TR[i][j], BL[i][j], BR[i][j]
            vals = [
                ('TL', tl),
                ('TR', tr),
                ('BL', bl),
                ('BR', br),
            ]

            # For each, get its quadrant's background
            # Priority: if cell != its quadrant bg, it's active. 
            # Then among active cells, first by priority order (TL, TR, BL, BR)

            found = None
            for qn, val in vals:
                if qn == 'TL': qb = mode(TL)
                elif qn == 'TR': qb = mode(TR)
                elif qn == 'BL': qb = mode(BL)
                else: qb = mode(BR)

                if val != qb:
                    found = val
                    break

            if found is None:
                row.append(bg)
            else:
                row.append(found)
        result.append(row)
    return result
